export function tallyBallots(
  ballots: readonly string[],
): ReadonlyMap<string, number> {
  const totals = new Map<string, number>();

  for (const ballot of ballots) {
    const separator = ballot.indexOf("|");
    if (separator <= 0 || ballot.indexOf("|", separator + 1) !== -1) {
      continue;
    }

    const topic = ballot.slice(0, separator);
    const rawWeight = ballot.slice(separator + 1);
    if (!/^[A-Z]{2,8}$/.test(topic)) {
      continue;
    }

    const weight = Number.parseInt(rawWeight, 10);
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      continue;
    }

    totals.set(topic, (totals.get(topic) ?? 0) + weight);
  }

  return totals;
}
```

